// lib/components/diode.ts
import { z as z76 } from "zod";
var diodeConnectionKeys = z76.enum([
  "anode",
  "cathode",
  "pin1",
  "pin2",
  "pos",
  "neg"
]);
var connectionTarget3 = z76.string().or(z76.array(z76.string()).readonly()).or(z76.array(z76.string()));
var connectionsProp2 = z76.record(diodeConnectionKeys, connectionTarget3);
var diodeVariant = z76.enum([
  "standard",
  "schottky",
  "zener",
  "avalanche",
  "photo",
  "tvs"
]);
var diodeProps = commonComponentProps.extend({
  connections: connectionsProp2.optional(),
  variant: diodeVariant.optional().default("standard"),
  standard: z76.boolean().optional(),
  schottky: z76.boolean().optional(),
  zener: z76.boolean().optional(),
  avalanche: z76.boolean().optional(),
  photo: z76.boolean().optional(),
  tvs: z76.boolean().optional(),
  schOrientation: schematicOrientation.optional()
}).superRefine((data, ctx) => {
  const enabledFlags = [
    data.standard,
    data.schottky,
    data.zener,
    data.avalanche,
    data.photo,
    data.tvs
  ].filter(Boolean).length;
  if (enabledFlags > 1) {
    ctx.addIssue({
      code: z76.ZodIssueCode.custom,
      message: "Exactly one diode variant must be enabled",
      path: []
    });
    return z76.INVALID;
  }
}).transform((data) => {
  const result = {
    ...data,
    standard: false,
    schottky: false,
    zener: false,
    avalanche: false,
    photo: false,
    tvs: false
  };
  if (data.standard) result.standard = true;
  else if (data.schottky) result.schottky = true;
  else if (data.zener) result.zener = true;
  else if (data.photo) result.photo = true;
  else if (data.tvs) result.tvs = true;
  else {
    switch (data.variant) {
      case "standard":
        result.standard = true;
        break;
      case "schottky":
        result.schottky = true;
        break;
      case "zener":
        result.zener = true;
        break;
      case "avalanche":
        result.avalanche = true;
        break;
      case "photo":
        result.photo = true;
        break;
      case "tvs":
        result.tvs = true;
        break;
      default:
        result.standard = true;
    }
  }
  return result;
});
var diodePins = lrPolarPins;
expectTypesMatch(true);

